mapper.sql:
n.deleted = 0
AND n.status = 'PUBLISHED'
AND (
    n.scope_type = 'ALL'

        OR EXISTS (
            SELECT 1
            FROM sys_notice_target nt
            WHERE nt.notice_id = n.id
            AND (
                1 = 0

                    OR (nt.target_type = 'ROLE' AND nt.target_id IN

                        #{roleId}

                    )


                    OR (nt.target_type = 'DEPT' AND nt.target_id IN

                        #{deptId}

                    )

            )
        )

)
